-- CONECTASUCRE | 13_03_MIGRAR_DATOS_POSTGRESQL.sql
-- Generado a partir del respaldo real Dump20261120.sql (15 tablas).
-- Ejecutar SOLO en pgAdmin > Query Tool conectado a conectasucre_final de PostgreSQL 17.
-- Requiere las 15 tablas y 20 FK ya creadas; no modifica MySQL.
-- Primera carga: transaccion atomica; si hay error, no se ejecuta COMMIT.
-- NO ejecutar dos veces; la verificacion de destino vacio impide duplicar.
BEGIN;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL statement_timeout = '0';

-- Seguridad: abortar si faltan tablas o si alguna ya contiene registros.
DO $migration_check$
DECLARE n integer; c bigint; r record;
BEGIN
  SELECT count(*) INTO n FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE';
  IF n <> 15 THEN RAISE EXCEPTION 'Se esperaban 15 tablas, encontradas %',n; END IF;
  FOR r IN SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' LOOP
    EXECUTE format('SELECT count(*) FROM public.%I',r.table_name) INTO c;
    IF c <> 0 THEN RAISE EXCEPTION 'La tabla % ya tiene % registros. Detener para evitar duplicados.', r.table_name, c; END IF;
  END LOOP;
END;
$migration_check$;

